-- =====================================================================
-- 02_modelo_dimensional.sql · OT Consulting · Equipo 3
-- Crea y llena las 7 dimensiones y 3 tablas de hechos del modelo (Kimball).
-- Portable: corre igual en MySQL 8 y en SQL Server 2016+ (solo INSERTs,
-- sin rutas de archivo). Datos tomados de docs/datos csv reto/clean_*.csv.
-- Datos sensibles (RFC, CURP, NSS, domicilio, teléfono) NO se incluyen.
-- Fechas 1990-01-01 (marcador de 'por confirmar') se guardan como NULL.
-- =====================================================================
-- MySQL:      CREATE DATABASE IF NOT EXISTS otc;  USE otc;
-- SQL Server: IF DB_ID('otc') IS NULL CREATE DATABASE otc;  (luego) USE otc;

DROP TABLE IF EXISTS fact_activo;
DROP TABLE IF EXISTS fact_habilidad_colaborador;
DROP TABLE IF EXISTS fact_asignacion;
DROP TABLE IF EXISTS dim_tiempo;
DROP TABLE IF EXISTS dim_activo;
DROP TABLE IF EXISTS dim_habilidad;
DROP TABLE IF EXISTS dim_cliente_proyecto;
DROP TABLE IF EXISTS dim_colaborador;
DROP TABLE IF EXISTS dim_rol;
DROP TABLE IF EXISTS dim_departamento;

CREATE TABLE dim_departamento (
  codigo_departamento VARCHAR(10) NOT NULL PRIMARY KEY,
  nombre VARCHAR(100) NOT NULL,
  objetivo VARCHAR(500) NULL,
  estatus VARCHAR(20) NULL
);
CREATE TABLE dim_rol (
  codigo_rol VARCHAR(10) NOT NULL PRIMARY KEY,
  nombre_del_rol VARCHAR(150) NOT NULL,
  nivel VARCHAR(30) NULL,
  codigo_departamento VARCHAR(10) NULL,
  descripcion VARCHAR(255) NULL,
  estatus VARCHAR(20) NULL,
  FOREIGN KEY (codigo_departamento) REFERENCES dim_departamento(codigo_departamento)
);
CREATE TABLE dim_colaborador (
  id_colaborador VARCHAR(10) NOT NULL PRIMARY KEY,
  nombre_completo VARCHAR(150) NOT NULL,
  genero VARCHAR(20) NULL,
  ciudad VARCHAR(100) NULL,
  estatus VARCHAR(20) NULL,
  fecha_incorporacion DATE NULL,
  fecha_de_baja DATE NULL,
  tipo_nomina VARCHAR(50) NULL,
  codigo_rol VARCHAR(10) NULL,
  puesto VARCHAR(150) NULL,
  departamento VARCHAR(100) NULL,
  sueldo_neto_total DECIMAL(12,2) NULL,
  comision_nomina DECIMAL(12,2) NULL,
  impuestos_imss DECIMAL(12,2) NULL,
  sueldo_total_integrado DECIMAL(12,2) NULL,
  costo_por_hora DECIMAL(10,2) NULL,
  revision_sueldo VARCHAR(30) NULL,
  estado_asignacion VARCHAR(40) NULL,
  FOREIGN KEY (codigo_rol) REFERENCES dim_rol(codigo_rol)
);
CREATE TABLE dim_cliente_proyecto (
  id_proyecto VARCHAR(10) NOT NULL PRIMARY KEY,
  cod_cliente VARCHAR(10) NULL,
  cliente VARCHAR(150) NULL,
  industria VARCHAR(100) NULL,
  estatus_cliente VARCHAR(20) NULL,
  proyecto VARCHAR(150) NULL,
  fecha_inicio DATE NULL,
  fecha_fin DATE NULL,
  pm_otc VARCHAR(150) NULL,
  estatus_proyecto VARCHAR(30) NULL,
  revision_fechas VARCHAR(60) NULL
);
CREATE TABLE dim_habilidad (
  id_habilidad VARCHAR(10) NOT NULL PRIMARY KEY,
  descripcion VARCHAR(150) NULL,
  tecnologia VARCHAR(100) NULL,
  tipo VARCHAR(10) NULL,
  estatus VARCHAR(20) NULL
);
CREATE TABLE dim_activo (
  cod_activo VARCHAR(10) NOT NULL PRIMARY KEY,
  descripcion VARCHAR(100) NULL,
  marca VARCHAR(60) NULL,
  modelo VARCHAR(100) NULL,
  serie VARCHAR(60) NULL,
  tipo VARCHAR(40) NULL,
  estatus VARCHAR(20) NULL
);
CREATE TABLE dim_tiempo (
  fecha DATE NOT NULL PRIMARY KEY,
  anio INT NOT NULL,
  trimestre INT NOT NULL,
  mes INT NOT NULL,
  nombre_mes VARCHAR(15) NOT NULL,
  anio_mes VARCHAR(7) NOT NULL,
  dia INT NOT NULL,
  dia_semana VARCHAR(12) NOT NULL,
  es_fin_de_semana INT NOT NULL
);
CREATE TABLE fact_asignacion (
  id_asignacion INT NOT NULL PRIMARY KEY,
  id_colaborador VARCHAR(10) NOT NULL,
  id_proyecto VARCHAR(10) NOT NULL,
  codigo_rol_interno VARCHAR(10) NULL,
  codigo_rol_asignado VARCHAR(10) NULL,
  tipo_de_asignacion VARCHAR(30) NULL,
  estatus_asignacion VARCHAR(30) NULL,
  fecha_inicio DATE NULL,
  fecha_fin DATE NULL,
  dias_para_finalizar INT NULL,
  estado_vencimiento VARCHAR(30) NULL,
  FOREIGN KEY (id_colaborador) REFERENCES dim_colaborador(id_colaborador),
  FOREIGN KEY (id_proyecto) REFERENCES dim_cliente_proyecto(id_proyecto),
  FOREIGN KEY (codigo_rol_interno) REFERENCES dim_rol(codigo_rol),
  FOREIGN KEY (codigo_rol_asignado) REFERENCES dim_rol(codigo_rol),
  FOREIGN KEY (fecha_inicio) REFERENCES dim_tiempo(fecha),
  FOREIGN KEY (fecha_fin) REFERENCES dim_tiempo(fecha)
);
CREATE TABLE fact_habilidad_colaborador (
  id_colaborador VARCHAR(10) NOT NULL,
  id_habilidad VARCHAR(10) NOT NULL,
  nivel VARCHAR(20) NOT NULL,
  nivel_numerico INT NOT NULL,
  PRIMARY KEY (id_colaborador, id_habilidad),
  FOREIGN KEY (id_colaborador) REFERENCES dim_colaborador(id_colaborador),
  FOREIGN KEY (id_habilidad) REFERENCES dim_habilidad(id_habilidad)
);
CREATE TABLE fact_activo (
  cod_activo VARCHAR(10) NOT NULL PRIMARY KEY,
  id_colaborador VARCHAR(10) NULL,
  fecha_inicio DATE NULL,
  fecha_fin DATE NULL,
  costo DECIMAL(12,2) NULL,
  revision_costo VARCHAR(40) NULL,
  revision_general VARCHAR(40) NULL,
  revision_asignacion VARCHAR(40) NULL,
  FOREIGN KEY (cod_activo) REFERENCES dim_activo(cod_activo),
  FOREIGN KEY (id_colaborador) REFERENCES dim_colaborador(id_colaborador),
  FOREIGN KEY (fecha_inicio) REFERENCES dim_tiempo(fecha),
  FOREIGN KEY (fecha_fin) REFERENCES dim_tiempo(fecha)
);

